//! cwRefine CPU recipe vs Python/production reference values.
//!
//! Fixtures: tests/fixtures/ (generated by parity/make_fixtures.py with the
//! original Python recipe: Pillow 12.1.1, OpenCV 4.13, transformers 4.57). Every case must match
//! EXACTLY (bit-for-bit u8; f32 for the HF normalisation).

use cwrefine::recipe::*;
use serde_json::Value;
use std::path::PathBuf;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}
fn manifest() -> Value {
    serde_json::from_str(&std::fs::read_to_string(dir().join("manifest.json")).unwrap()).unwrap()
}
fn bytes(v: &Value) -> Vec<u8> {
    std::fs::read(dir().join(v["file"].as_str().unwrap())).unwrap()
}
fn shape(v: &Value) -> Vec<usize> {
    v["shape"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as usize).collect()
}
fn cases(kind: &str) -> Vec<Value> {
    manifest()["cases"].as_array().unwrap().iter().filter(|c| c["kind"] == kind).cloned().collect()
}
fn morph_src() -> (Vec<u8>, usize, usize) {
    let c = &cases("morph_src")[0];
    let s = shape(&c["src"]);
    (bytes(&c["src"]), s[1], s[0])
}
fn ndiff(a: &[u8], b: &[u8]) -> usize {
    a.iter().zip(b).filter(|(x, y)| x != y).count()
}

#[test]
fn lanczos_matches_pillow() {
    let cs = cases("lanczos");
    assert!(cs.len() >= 9);
    for c in cs {
        let s = shape(&c["src"]);
        let ch = if c["mode"] == "RGB" { 3 } else { 1 };
        let (dw, dh) = (c["dw"].as_u64().unwrap() as usize, c["dh"].as_u64().unwrap() as usize);
        let got = lanczos_u8(&bytes(&c["src"]), s[1], s[0], ch, dw, dh);
        let want = bytes(&c["dst"]);
        assert_eq!(got.len(), want.len());
        assert_eq!(ndiff(&got, &want), 0, "lanczos {} {}x{} -> {dw}x{dh}", c["mode"], s[1], s[0]);
    }
}

#[test]
fn ellipse_kernels_match_opencv() {
    for c in cases("ellipse") {
        let k = c["k"].as_u64().unwrap() as usize;
        let se = bytes(&c["se"]);
        let mut mine = vec![0u8; k * k];
        for (dy, a, b) in ellipse_rows(k) {
            for dx in a..=b {
                mine[(dy + (k / 2) as i32) as usize * k + (dx + (k / 2) as i32) as usize] = 1;
            }
        }
        assert_eq!(mine, se, "ellipse k={k}");
    }
}

#[test]
fn dilate_erode_match_opencv() {
    let (m, w, h) = morph_src();
    let mut n = 0;
    for kind in ["dilate", "erode"] {
        for c in cases(kind) {
            let k = c["k"].as_u64().unwrap() as usize;
            let got = if kind == "dilate" { dilate_ellipse(&m, w, h, k) } else { erode_ellipse(&m, w, h, k) };
            assert_eq!(ndiff(&got, &bytes(&c["dst"])), 0, "{kind} k={k}");
            n += 1;
        }
    }
    assert!(n >= 16);
}

#[test]
fn predilate_matches_opencv_rect() {
    let (m, w, h) = morph_src();
    for c in cases("predilate") {
        let p = c["pd"].as_u64().unwrap() as usize;
        assert_eq!(ndiff(&dilate_rect(&m, w, h, p), &bytes(&c["dst"])), 0, "pre-dilate {p}");
    }
}

#[test]
fn trimap_matches_production() {
    let (m, w, h) = morph_src();
    let cs = cases("trimap");
    assert!(cs.len() >= 6);
    for c in cs {
        let asym = match (c["kernel_inward"].as_u64(), c["kernel_outward"].as_u64()) {
            (Some(a), Some(b)) => Some((a as usize, b as usize)),
            _ => None,
        };
        let p = TrimapParams {
            kernel_size: c["kernel_size"].as_u64().unwrap() as usize,
            asym,
            mid_point: None,
            mid_bias: c["mid_bias"].as_f64(),
            seed_clamp: c["seed_clamp"].as_i64().unwrap() as i32,
        };
        assert_eq!(ndiff(&gen_trimap(&m, w, h, &p), &bytes(&c["dst"])), 0, "trimap {p:?}");
    }
}

#[test]
fn crop_plans_match_production() {
    for c in cases("crop") {
        let b: Vec<usize> = c["bbox"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        let g = |k: &str| c[k].as_u64().unwrap() as usize;
        let p = crop_plan(g("W"), g("H"), (b[0], b[1], b[2], b[3]), g("pad"), g("max_crop"));
        let want: Vec<usize> = c["box"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        let proc: Vec<usize> = c["proc"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        let padded: Vec<usize> = c["padded"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        match p {
            Some(p) => {
                assert_eq!(vec![p.x0, p.y0, p.x1, p.y1], want, "{c}");
                assert_eq!(vec![p.pw, p.ph], proc, "{c}");
                assert_eq!(vec![p.padw, p.padh], padded, "{c}");
            }
            None => assert!(want[2] <= want[0] || want[3] <= want[1], "unexpected None for {c}"),
        }
    }
}

#[test]
fn hf_normalisation_matches_processor() {
    let c = &cases("hfnorm")[0];
    let s = shape(&c["img"]);
    let (h, w) = (s[0], s[1]);
    let pv = hf_pixel_values(&bytes(&c["img"]), &bytes(&c["tri"]), w, h);
    let want: Vec<f32> = bytes(&c["pv"]).chunks_exact(4).map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]])).collect();
    assert_eq!(shape(&c["pv"]), vec![1, 4, h, w]);
    let worst = pv.iter().zip(&want).map(|(a, b)| (a - b).abs()).fold(0f32, f32::max);
    assert_eq!(worst, 0.0, "max |rust - HF| = {worst}");
}
